import assert from 'node:assert/strict';
import{readFile,writeFile}from'node:fs/promises';
import{resolve,join}from'node:path';
import{pathToFileURL}from'node:url';
const dir=resolve(process.argv[2]);
const {metadata}=await import(pathToFileURL(join(dir,'program.mjs')).href);
let code=await readFile(join(dir,'program.mjs'),'utf8');
const index=metadata.functions.find(f=>f.name==='default_config').index;
const pattern=new RegExp('function __fn'+index+'\\([^)]*\\)\\{');assert(pattern.test(code));
code=code.replace(pattern,m=>m+'globalThis.__defaultConfigBuilds++;');
await writeFile(join(dir,'instrumented.mjs'),code);globalThis.__defaultConfigBuilds=0;
const{createState}=await import(pathToFileURL(join(dir,'instrumented.mjs')).href);
const state=createState();assert.equal(globalThis.__defaultConfigBuilds,0);const call=(n,...args)=>state.invoke(n,args).result;
const first=call('left');assert.equal(globalThis.__defaultConfigBuilds,1);
assert.deepEqual(call('right'),first);assert.equal(globalThis.__defaultConfigBuilds,1);
assert.deepEqual(call('maybe'),{Err:'default unavailable'});assert.deepEqual(call('maybe'),{Err:'default unavailable'});
first.values.fill(99);first.next.Some.label='attacked';assert.notDeepEqual(call('left'),first);assert.deepEqual(call('left'),call('right'));
const seed=call('seed');seed.values.fill(77);seed.label='attacked';assert.notDeepEqual(call('right'),seed);
assert.deepEqual(call('scoped',[10,20]),[call('left'),call('left')]);
const input={label:'new',values:[0.25,-0],next:{None:null}};const saved=structuredClone(input);
call('set_left',input);input.values.fill(77);input.label='attacked';assert.deepEqual(call('left'),saved);
assert.notDeepEqual(call('left'),call('right'));call('copy');assert.deepEqual(call('right'),saved);
call('unrelated',5);assert.deepEqual(call('right'),saved);assert.equal(globalThis.__defaultConfigBuilds,1);
const typed=state.bind('set_left',{resultOnly:true});typed(saved);saved.values.fill(99);assert.notDeepEqual(call('left'),saved);
const before=await state.checkpoint();assert.deepEqual(call('cancel',input),{Err:'cancel'});assert.deepEqual(await state.checkpoint(),before);
state.beginTransaction();call('set_left',input);state.rollbackTransaction();assert.deepEqual(await state.checkpoint(),before);
assert.equal(globalThis.__defaultConfigBuilds,1);await state.restore(before);assert.equal(globalThis.__defaultConfigBuilds,1);call('right');assert.equal(globalThis.__defaultConfigBuilds,2);
console.log('Prepared defaults: shared immutable seeds, source Err values, lexical capture, detached public/typed inputs, rollback and restore.');
